import{_ as s,l,o as e,c as o,v as t,p as n,x as i,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"关键路径调度","description":"","frontmatter":{"title":"关键路径调度","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/critical-path-scheduling.md","filePath":"cs/critical-path-scheduling.md","lastUpdated":1789023840000}'),h={name:"cs/critical-path-scheduling.md"};function A(_,a,u,m,E,f){const r=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="关键路径调度" tabindex="-1">关键路径调度 <a class="header-anchor" href="#关键路径调度" aria-label="Permalink to &quot;关键路径调度&quot;">​</a></h1><div class="epigraph"><p>DAG 上最长加权路径决定块的下界周期。优先级让关键路径上的节点先发，避免闲置把下界再拉长。</p><footer>—— 据 Hu 的表调度传统；Hennessy and Gross；龙书指令调度；组成课[关键路径](/cs/critical-path) 对照整理</footer></div><p>上一课<a href="/cs/software-pipelining">软件流水</a>用 RecMII（环上关键）。块内同样：无环 DAG 的关键路径长度是表调度的下界。缺口是把组成课门级关键路径的直觉<strong>搬到指令 DAG</strong>（延迟为边权）。本课钉高度函数与为何「先发关键」，不写时钟树。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>就绪表若总发短延迟、非关键指令，关键节点被挤到后面，总拍数超过下界。优先级：节点高度 = 到出口的最长路径。缺口是<strong>这个下界与启发式</strong>，不是模 II。</p><p>寄存器压力：全按高度可能瞬时活太多，需混合优先级。</p><h3 id="指令关键路径不是-sta-的门延迟" tabindex="-1">指令关键路径不是 STA 的门延迟 <a class="header-anchor" href="#指令关键路径不是-sta-的门延迟" aria-label="Permalink to &quot;指令关键路径不是 STA 的门延迟&quot;">​</a></h3><p>STA 是芯片；这里边权是指令延迟表（ISA/微架构模型）。模型错则调度错，不是硅上时序违例。</p><p><span class="marginnote">经典 list scheduling 用 height/latency。组成课 critical-path 是电路。本课明确不重画时钟树。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从 DAG 汇点反向最长路。就绪时选高度最大。打破平局：延迟大、或扇出大。与资源（单端口乘）结合：资源可用才就绪。</p>',11)),(e(),n(p,null,{default:i(()=>[d(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DAG%5B%22%E6%8C%87%E4%BB%A4%20DAG%22%5D%20--%3E%20H%5B%22%E9%AB%98%E5%BA%A6%20%3D%20%E6%9C%80%E9%95%BF%E8%B7%AF%22%5D%0A%20%20H%20--%3E%20LIST%5B%22%E8%A1%A8%E8%B0%83%E5%BA%A6%E4%BC%98%E5%85%88%E7%BA%A7%22%5D%0A%20%20LIST%20--%3E%20LB%5B%22%E6%8E%A5%E8%BF%91%E4%B8%8B%E7%95%8C%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与软件流水：RecMII 就是环上关键路径 / 迭代。同一度量，拓扑有环。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>下界不可达：资源冲突。启发式无保证。不要把关键路径当「必须连续发射」，中间可插独立指令填槽——那正是表调度的工作。</p><p>PGO：热块更值得按精确延迟模型排。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写电路 STA。后课默认：高度驱动表调度。下一课树匹配指令选择：调度前还要先选对指令。</p><p>也不把关键路径当项目管理。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>块内下界 = DAG 关键路径；高度优先逼近它。</li><li>资源约束使下界不可达。</li><li>与模调度的 RecMII 同源。</li><li>出处：Hennessy and Gross；龙书；对照组成课关键路径（不同对象）。</li></ul>',9))])}const S=s(h,[["render",A]]);export{T as __pageData,S as default};
